18	std::atomic<uint64_t> g_dynamicWriteIdx{0};
19	std::atomic<uint64_t> g_staticWriteIdx{0};
20	
21	constexpr uint64_t MAGIC_NUM = 0xA5A5A5A500000000;
22	constexpr uint64_t FLIP_NUM_MASK = 0b01111111;
23	constexpr uint16_t FLIP_NUM_SHIFT_BITS = 24;
24	constexpr uint64_t STATIC_BUFFER_ID = 0x080000000;
25	}  // namespace
26	
27	void *AdumpGetDFXInfoAddrForDynamic(uint32_t space, uint64_t &atomicIndex)
28	{
29	    if (space > DFX_MAX_TENSOR_NUM || g_dynamicChunk == nullptr) {
30	        return nullptr;
31	    }
32	
33	    auto nextWriteCursor = g_dynamicWriteIdx.fetch_add(space + RESERVE_SPACE);
34	    uint64_t flipNum = nextWriteCursor / DYNAMIC_RING_CHUNK_SIZE;
35	    uint64_t offset = nextWriteCursor % DYNAMIC_RING_CHUNK_SIZE;
36	    atomicIndex = MAGIC_NUM | ((flipNum & FLIP_NUM_MASK) << FLIP_NUM_SHIFT_BITS) | offset;
37	    g_dynamicChunk[offset] = MAGIC_NUM | space;
38	    g_dynamicChunk[offset + 1] = atomicIndex;
39	    return g_dynamicChunk + offset + RESERVE_SPACE;
40	}
41	
42	void *AdumpGetDFXInfoAddrForStatic(uint32_t space, uint64_t &atomicIndex)
43	{
44	    if (space > DFX_MAX_TENSOR_NUM || g_staticChunk == nullptr) {
45	        return nullptr;
46	    }
47	
48	    auto nextWriteCursor = g_staticWriteIdx.fetch_add(space + RESERVE_SPACE);
49	    uint64_t flipNum = nextWriteCursor / STATIC_RING_CHUNK_SIZE;
50	    uint64_t offset = nextWriteCursor % STATIC_RING_CHUNK_SIZE;
51	    atomicIndex = MAGIC_NUM | STATIC_BUFFER_ID | ((flipNum & FLIP_NUM_MASK) << FLIP_NUM_SHIFT_BITS) | offset;
52	    g_staticChunk[offset] = MAGIC_NUM | space;
53	    g_staticChunk[offset + 1] = atomicIndex;
54	    return g_staticChunk + offset + RESERVE_SPACE;
55	}
