123	void *AdumpGetSizeInfoAddr(uint32_t space, uint32_t &atomicIndex)
124	{
125	    if (!g_setAssert) {
126	        const std::lock_guard<std::mutex> lock(g_setAssertMtx);
127	        if (!g_setAssert) {
128	            (void)rtSetTaskFailCallback(AdxAssertCallBack);
129	            g_setAssert = true;
130	        }
131	    }
132	    if (space > MAX_TENSOR_NUM) {
133	        return nullptr;
134	    }
135	
136	    atomicIndex = g_atomicIndex++;
137	    auto nextWriteCursor = g_writeIdx.fetch_add(space);
138	    return g_chunk + (nextWriteCursor % RING_CHUNK_SIZE);
139	}
