60	std::string CurrentTimeFormatStr()
61	{
62	    std::string time_str;
63	    auto now = std::chrono::system_clock::now();
64	    auto milli_seconds = std::chrono::time_point_cast<std::chrono::milliseconds>(now);
65	    auto micro_seconds = std::chrono::time_point_cast<std::chrono::microseconds>(now);
66	    const auto now_t = std::chrono::system_clock::to_time_t(now);
67	    const std::tm* tm_now = std::localtime(&now_t);
68	    if (tm_now == nullptr) {
69	        return time_str;
70	    }
71	
72	    constexpr int32_t year_base = 1900;
73	    constexpr size_t kMaxTimeLen = 128U;
74	    constexpr int64_t kOneThousandMs = 1000L;
75	    error_message::char_t format_time[kMaxTimeLen] = {};
76	    (void)snprintf_s(
77	        format_time, kMaxTimeLen, kMaxTimeLen - 1U, "%04d-%02d-%02d-%02d:%02d:%02d.%03ld.%03ld",
78	        tm_now->tm_year + year_base, tm_now->tm_mon + 1, tm_now->tm_mday, tm_now->tm_hour, tm_now->tm_min,
79	        tm_now->tm_sec, milli_seconds.time_since_epoch().count() % kOneThousandMs,
80	        micro_seconds.time_since_epoch().count() % kOneThousandMs);
81	    time_str = format_time;
82	    return time_str;
83	}
