48	/**
49	 * @brief: send result to host through adcore
50	 * @param [in] handle: hdc handle
51	 * @param [in] resultBuf: result buffer pointer
52	 * @param [in] resultLen: result buffer used length
53	 * @param [in] isError: if error occur
54	 * @return: CONFIG_OK: succeed; others: failed
55	 */
56	STATIC int32_t CmdRespSettingResult(const CommHandle *handle, const char *resultBuf, size_t resultLen, bool isError)
57	{
58	    size_t configLen = resultLen + 1U;
59	    size_t buffLen = sizeof(struct ConfigInfo) + configLen;
60	    struct ConfigInfo *configInfo = (struct ConfigInfo *)LogMalloc(buffLen);
61	    ONE_ACT_ERR_LOG(configInfo == NULL, return CONFIG_MALLOC_FAILED, "malloc failed.");
62	    
63	    configInfo->len = (uint32_t)configLen;
64	    configInfo->isError = isError;
65	    int32_t ret = memcpy_s(configInfo->value, configLen, resultBuf, resultLen);
66	    TWO_ACT_ERR_LOG(ret != EOK, XFREE(configInfo), return CONFIG_MEM_WRITE_FAILED, "memcpy_s failed, ret:%d", ret);
67	
68	    ret = AdxSendMsgByHandle(handle, IDE_MSN_REQ, (char *)configInfo, (uint32_t)buffLen);
69	    if (isError) {
70	        SELF_LOG_ERROR("send configInfo->len:%u, configInfo->value:%s, return:%d",
71	            configInfo->len, configInfo->value, ret);
72	    } else {
73	        SELF_LOG_INFO("send configInfo->len:%u, configInfo->value:%s, return:%d",
74	            configInfo->len, configInfo->value, ret);
75	    }
76	    if (ret != IDE_DAEMON_OK) {
77	        XFREE(configInfo);
78	        SELF_LOG_ERROR("write result to host failed, return:%d.", ret);
79	        return CONFIG_ERROR;
80	    }
81	    XFREE(configInfo);
82	
83	    return CONFIG_OK;
84	}
