58	aclError CheckAclProfSetConfigInput(aclprofConfigType configType, const char* config, size_t configLength)
59	{
60	    if (configType <= ACL_PROF_ARGS_MIN || configType >= ACL_PROF_ARGS_MAX) {
61	        MSPROF_LOGE("[aclprofSetConfig]ConfigType %d is not support.", static_cast<int32_t>(configType));
62	        std::string reason = "configType should be greater than ACL_PROF_ARGS_MIN and less than ACL_PROF_ARGS_MAX";
63	        MSPROF_INPUT_ERROR(
64	            "EK0001", std::vector<std::string>({"value", "param", "reason"}),
65	            std::vector<std::string>({std::to_string(static_cast<int32_t>(configType)), "configType", reason}));
66	        return ACL_ERROR_INVALID_PARAM;
67	    }
68	    if (configLength > configMaxLength) {
69	        MSPROF_LOGE(
70	            "length of config is illegal, the value is %zu, it should be in (0, %zu)", configLength, configMaxLength);
71	        std::string reason = "configLength should be less than or equal to " + std::to_string(configMaxLength);
72	        MSPROF_INPUT_ERROR(
73	            "EK0001", std::vector<std::string>({"value", "param", "reason"}),
74	            std::vector<std::string>({std::to_string(configLength), "configLength", reason}));
75	        return ACL_ERROR_INVALID_PARAM;
76	    }
77	    if (config == nullptr) {
78	        MSPROF_LOGE("[aclprofSetConfig]Input value is nullptr.");
79	        MSPROF_INPUT_ERROR(
80	            "EK0006", std::vector<std::string>({"api", "param"}),
81	            std::vector<std::string>({"aclprofSetConfig", "config"}));
82	        return ACL_ERROR_INVALID_PARAM;
83	    }
84	    if (strlen(config) != configLength) {
85	        MSPROF_LOGE("[aclprofSetConfig]Input value is nullptr or its length does not equal to given length.");
86	        MSPROF_INPUT_ERROR(
87	            "EK0001", std::vector<std::string>({"value", "param", "reason"}),
88	            std::vector<std::string>(
89	                {std::to_string(configLength), "configLength", "configLength does not equal to strlen(config)"}));
90	        return ACL_ERROR_INVALID_PARAM;
91	    }
92	    return ACL_SUCCESS;
93	}
