95	aclError CheckProfInitPath(CONST_CHAR_PTR profilerResultPath, size_t length)
96	{
97	    if (profilerResultPath == nullptr) {
98	        MSPROF_LOGE("ProfilerResultPath is nullptr");
99	        MSPROF_INPUT_ERROR(
100	            "EK0006", std::vector<std::string>({"api", "param"}),
101	            std::vector<std::string>({"aclprofInit", "profilerResultPath"}));
102	        return ACL_ERROR_INVALID_PARAM;
103	    }
104	
105	    if (length >= aclProfPathMaxLen || length == 0) {
106	        MSPROF_LOGE("Length of profilerResultPath is illegal, which should be in (0, %zu)", aclProfPathMaxLen);
107	        std::string errorReason =
108	            "Length of profilerResultPath should be in [1, " + std::to_string(aclProfPathMaxLen) + ")";
109	        MSPROF_INPUT_ERROR(
110	            "EK0001", std::vector<std::string>({"value", "param", "reason"}),
111	            std::vector<std::string>({std::to_string(length), "profilerResultPath length", errorReason}));
112	        return ACL_ERROR_INVALID_PARAM;
113	    }
114	
115	    if (strlen(profilerResultPath) != length) {
116	        MSPROF_LOGE("Length of profilerResultPath does not equal to given length");
117	        std::string errorReason = "Length of profilerResultPath does not equal to strlen(profilerResultPath)";
118	        MSPROF_INPUT_ERROR(
119	            "EK0001", std::vector<std::string>({"value", "param", "reason"}),
120	            std::vector<std::string>({std::to_string(length), "profilerResultPath length", errorReason}));
121	        return ACL_ERROR_INVALID_PARAM;
122	    }
123	    return ACL_SUCCESS;
124	}
